namespace Facebook\AutoloadMap;

/** Class to write `hh_autoload.php`.
 *
 * This includes:
 * - the autoload map
 * - any files to explicitly require
 * - several autogenerated convenience functions
 * - the failure handler
 */
final class Writer {
  private ?ImmVector<string> $files;
  private ?AutoloadMap $map;
  private ?string $root;
  private bool $relativeAutoloadRoot = true;
  private ?string $failureHandler;
  private bool $isDev = true;

  /** Mark whether we're running in development mode.
   *
   * This is only used for `Generated\is_dev()` - the map should already be
   * filtered appropriately.
   */
  public function setIsDev(bool $is_dev): this {
    $this->isDev = $is_dev;
    return $this;
  }

  /** Class to use to handle lookups for items not in the map */
  public function setFailureHandler(?classname<FailureHandler> $handler): this {
    $this->failureHandler = $handler;
    return $this;
  }

  /** Files to explicitly include */
  public function setFiles(ImmVector<string> $files): this {
    $this->files = $files;
    return $this;
  }

  /** The actual autoload map */
  public function setAutoloadMap(AutoloadMap $map): this {
    $this->map = $map;
    return $this;
  }

  /** Set the files and maps from a builder.
   *
   * Convenience function; this is equivalent to calling `setFiles()` and
   * `setAutoloadMap()`.
   */
  public function setBuilder(Builder $builder): this {
    $this->files = $builder->getFiles();
    $this->map = $builder->getAutoloadMap();
    return $this;
  }

  /** Set the root directory of the project */
  public function setRoot(string $root): this {
    $this->root = \realpath($root);
    return $this;
  }

  /** Set whether the autoload map should contain relative or absolute paths */
  public function setRelativeAutoloadRoot(bool $relative): this {
    $this->relativeAutoloadRoot = $relative;
    return $this;
  }

  /** Write the file to disk.
   *
   * You will need to call these first:
   * - `setFiles()`
   * - `setAutoloadMap()`
   * - `setIsDev()`
   */
  public function writeToFile(
    string $destination_file,
  ): this {
    $files = $this->files;
    $map = $this->map;
    $is_dev = $this->isDev;

    if ($files === null) {
      throw new Exception('Call setFiles() before writeToFile()');
    }
    if ($map === null) {
      throw new Exception('Call setAutoloadMap() before writeToFile()');
    }
    if ($is_dev === null) {
      throw new Exception('Call setIsDev() before writeToFile()');
    }
    $is_dev = $is_dev ? 'true' : 'false';

    $failure_handler = $this->failureHandler;
    if ($failure_handler !== null) {
      $failure_handler = self::validateFailureHandler($failure_handler, $map);
    }

    if ($this->relativeAutoloadRoot) {
      $root = '__DIR__.\'/../\'';
      $requires = $files->map(
        $file ==> '__DIR__.'.\var_export(
          '/../'.$this->relativePath($file),
          true,
        ),
      );
    } else {
      $root = \var_export($this->root.'/', true);
      $requires = $files->map(
        $file ==> \var_export(
          $this->root.'/'.$this->relativePath($file),
          true,
        ),
      );
    }

    $requires = \implode(
      "\n",
      $requires->map($require ==> 'require_once('.$require.');'),
    );

    $map = \array_map(
      function ($sub_map): mixed {
        assert(is_array($sub_map));
        return \array_map(
          $path ==> $this->relativePath($path),
          $sub_map,
        );
      },
      Shapes::toArray($map),
    );

    if ($failure_handler !== null) {
      $add_failure_handler = \sprintf(
        "\$handler_class = %s;\n".
        "if (\n".
        "  \\is_subclass_of(\$handler_class, %s) &&\n".
        "  \$handler_class::isEnabled()\n".
        ") {\n".
        "  \$handler = new \$handler_class();\n".
        "  \$map['failure'] = [\$handler, 'handleFailure'];\n".
        "  \HH\autoload_set_paths(\$map, root());\n".
        "  \$handler->initialize();\n".
        "}",
        \var_export($failure_handler, true),
        \var_export(FailureHandler::class, true),
      );
    } else {
      $add_failure_handler = null;
    }

    $build_id = \var_export(
      \date(\DateTime::ATOM).'!'.\bin2hex(\random_bytes(16)),
      true,
    );

    $map = \var_export($map, true);
    $code = <<<EOF
<?php

/// Generated file, do not edit by hand ///

namespace Facebook\AutoloadMap\Generated;

function build_id() {
  return $build_id;
}

function root() {
  return $root;
}

function is_dev() {
  return $is_dev;
}

function map() {
  return $map;
}

$requires

\$map = map();

\HH\autoload_set_paths(\$map, root());
foreach (\spl_autoload_functions() ?: [] as \$autoloader) {
  \spl_autoload_unregister(\$autoloader);
}

$add_failure_handler
EOF;
    \file_put_contents(
      $destination_file,
      $code,
    );

    return $this;
  }

  /** Return the failure handler class name to emit, or throw.
   *
   * The returned name is written into `hh_autoload.php`, so anything other
   * than a single class identifier must be rejected here.
   *
   * Handlers that can't be loaded yet are accepted if the map being written
   * defines them; the generated file checks their parent class at runtime.
   */
  private static function validateFailureHandler(
    string $handler,
    AutoloadMap $map,
  ): string {
    $is_name = \preg_match(
      '/\A\\\\?[a-zA-Z_\x80-\xff][a-zA-Z0-9_\x80-\xff]*'.
      '(?:\\\\[a-zA-Z_\x80-\xff][a-zA-Z0-9_\x80-\xff]*)*\z/',
      $handler,
    );
    if ($is_name !== 1) {
      throw new ConfigurationException(
        'Failure handler %s is not a class name',
        \var_export($handler, true),
      );
    }
    $name = \ltrim($handler, '\\');

    if (\class_exists($name)) {
      if (
        !\is_subclass_of($name, FailureHandler::class) ||
        (new \ReflectionClass($name))->isAbstract()
      ) {
        throw new ConfigurationException(
          'Failure handler %s is not a concrete subclass of %s',
          $name,
          FailureHandler::class,
        );
      }
      return $name;
    }

    if (\array_key_exists(\strtolower($name), $map['class'])) {
      return $name;
    }

    throw new ConfigurationException(
      'Failure handler class %s does not exist',
      $name,
    );
  }

  <<__Memoize>>
  private function relativePath(
    string $path,
  ): string {
    $root = $this->root;
    if ($root === null) {
      throw new Exception('Call setRoot() before writeToFile()');
    }
    $path = \realpath($path);
    if (\strpos($path, $root) !== 0) {
      throw new Exception(
        "%s is outside root %s",
        $path,
        $root,
      );
    }
    return \substr($path, \strlen($root) + 1);
  }
}
